import heapq

class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        # 用最小堆维护『当前最大的 k 个数』，堆顶即第 k 大
        heap = nums[:k]
        heapq.heapify(heap)              # O(k) 原地建堆
        for x in nums[k:]:
            if x > heap[0]:              # 比 k 个候选中最小的还大，才有资格入选
                heapq.heapreplace(heap, x)   # 弹出堆顶并压入 x，一次堆操作完成
        return heap[0]                   # 堆顶 = 前 k 大中最小的 = 第 k 大

