class Solution {
public:
    int findKthLargest(vector<int>& nums, int k) {
        // 用最小堆维护『当前最大的 k 个数』，堆顶即第 k 大
        priority_queue<int, vector<int>, greater<int>> heap;
        for (int x : nums) {
            if ((int)heap.size() < k) {
                heap.push(x);              // 前 k 个直接入堆
            } else if (x > heap.top()) {
                heap.pop();                // 比当前第 k 大的候选大才入堆
                heap.push(x);              // 弹出最小候选并压入 x
            }
        }
        return heap.top();                 // 堆顶 = 前 k 大中最小 = 第 k 大
    }
};

