var findKthLargest = function (nums, k) {
  // 手写大小为 k 的最小堆（JS 无内置堆），堆顶是 k 个候选中最小的，即第 k 大
  const heap = [];
  const push = (x) => {
    heap.push(x);                // 新元素先放到堆底
    let i = heap.length - 1;
    while (i > 0) {              // 上浮：比父节点小就交换
      const p = (i - 1) >> 1;
      if (heap[i] >= heap[p]) break;
      [heap[i], heap[p]] = [heap[p], heap[i]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0];         // 弹出堆顶（最小候选）
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;            // 末尾元素补到堆顶
      let i = 0;
      for (;;) {                 // 下沉：与较小的孩子交换
        const l = 2 * i + 1, r = 2 * i + 2;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]];
        i = m;
      }
    }
    return top;
  };

  for (const x of nums) {
    if (heap.length < k) {
      push(x);                   // 前 k 个直接入堆
    } else if (x > heap[0]) {
      pop();                     // 比当前第 k 大的候选大才替换
      push(x);
    }
  }
  return heap[0];                // 堆顶 = 前 k 大中最小 = 第 k 大
};

