func findKthLargest(nums []int, k int) int {
	// 手写大小为 k 的最小堆（上浮/下沉两个 sift 操作），堆顶即第 k 大
	heap := make([]int, 0, k)
	push := func(x int) {
		heap = append(heap, x) // 新元素先放到堆底
		i := len(heap) - 1
		for i > 0 { // 上浮：比父节点小就交换
			p := (i - 1) / 2
			if heap[i] >= heap[p] {
				break
			}
			heap[i], heap[p] = heap[p], heap[i]
			i = p
		}
	}
	pop := func() int {
		top := heap[0]              // 弹出堆顶（最小候选）
		heap[0] = heap[len(heap)-1] // 末尾元素补到堆顶
		heap = heap[:len(heap)-1]
		i, sz := 0, len(heap)
		for { // 下沉：与较小的孩子交换
			l, r, m := 2*i+1, 2*i+2, i
			if l < sz && heap[l] < heap[m] {
				m = l
			}
			if r < sz && heap[r] < heap[m] {
				m = r
			}
			if m == i {
				break
			}
			heap[i], heap[m] = heap[m], heap[i]
			i = m
		}
		return top
	}

	for _, x := range nums {
		if len(heap) < k {
			push(x) // 前 k 个直接入堆
		} else if x > heap[0] {
			pop() // 比当前第 k 大的候选大才替换
			push(x)
		}
	}
	return heap[0] // 堆顶 = 前 k 大中最小 = 第 k 大
}

