    for x in nums:
        freq[x] += 1
    buckets = [[] for _ in range(n + 1)]   # 下标 = 频率（1..n）
    for key, cnt in freq.items():
        buckets[cnt].append(key)
    ans = []
    for cnt in range(n, 0, -1):        # 从高频到低频收集
        for key in buckets[cnt]:
            ans.append(key)
            if len(ans) == k:
                return ans
    return ans

