import heapq
from collections import defaultdict

class Solution:
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        # 第一步：哈希表统计每个元素的出现频率
        freq = defaultdict(int)
        for x in nums:
            freq[x] += 1
        # 第二步：用大小为 k 的最小堆维护频率最高的 k 个元素
        # 堆中存 (频率, 元素) 元组，heapq 自动按第一个分量（频率）比较
        heap = []
        for key, cnt in freq.items():
            if len(heap) < k:
                heapq.heappush(heap, (cnt, key))   # 堆未满，直接放入候选
            elif cnt > heap[0][0]:
                # 当前频率高于堆顶（k 个候选中最低的），替换堆顶淘汰旧候选
                heapq.heapreplace(heap, (cnt, key))
        # 第三步：堆里剩下的就是前 k 高频元素
        return [key for _, key in heap]

