class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        // 第一步：哈希表统计每个元素的出现频率
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : nums)
            freq.put(x, freq.getOrDefault(x, 0) + 1);
        // 第二步：用大小为 k 的最小堆维护频率最高的 k 个 (频率, 元素) 对
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            int val = e.getKey(), cnt = e.getValue();
            if (heap.size() < k) {
                heap.offer(new int[]{cnt, val});   // 堆未满，直接放入候选
            } else if (cnt > heap.peek()[0]) {
                heap.poll();                       // 高于当前第 k 高频才替换
                heap.offer(new int[]{cnt, val});
            }
        }
        // 第三步：堆里剩下的就是前 k 高频元素
        int[] ans = new int[heap.size()];
        for (int i = 0; i < ans.length; i++)
            ans[i] = heap.poll()[1];
        return ans;
    }
}

