func topKFrequent(nums []int, k int) []int {
	// 第一步：哈希表统计每个元素的出现频率
	freq := map[int]int{}
	for _, x := range nums {
		freq[x]++
	}
	type pair struct {
		cnt int // 频率
		val int // 元素
	}
	// 第二步：大小为 k 的最小堆（按频率比较），手写 sift 不依赖标准库
	heap := []pair{}
	push := func(p pair) {
		heap = append(heap, p) // 新元素先放到堆底
		i := len(heap) - 1
		for i > 0 { // 上浮：频率比父节点小就交换
			par := (i - 1) / 2
			if heap[i].cnt >= heap[par].cnt {
				break
			}
			heap[i], heap[par] = heap[par], heap[i]
			i = par
		}
	}
	pop := func() pair {
		top := heap[0] // 弹出频率最低的候选
		last := heap[len(heap)-1]
		heap = heap[:len(heap)-1]
		if len(heap) > 0 {
			heap[0] = last // 末尾元素补到堆顶
			i, sz := 0, len(heap)
			for { // 下沉：与频率较小的孩子交换
				l, r, m := 2*i+1, 2*i+2, i
				if l < sz && heap[l].cnt < heap[m].cnt {
					m = l
				}
				if r < sz && heap[r].cnt < heap[m].cnt {
					m = r
				}
				if m == i {
					break
				}
				heap[i], heap[m] = heap[m], heap[i]
				i = m
			}
		}
		return top
	}

	for val, cnt := range freq {
		if len(heap) < k {
			push(pair{cnt, val}) // 堆未满，直接放入候选
		} else if cnt > heap[0].cnt {
			pop() // 高于当前第 k 高频才替换
			push(pair{cnt, val})
		}
	}
	// 第三步：堆里剩下的就是前 k 高频元素
	ans := make([]int, 0, len(heap))
	for _, p := range heap {
		ans = append(ans, p.val)
	}
	return ans
}

