import bisect

class MedianFinderArray:
    def __init__(self):
        self.arr = []                      # 始终有序的数组

    def addNum(self, num):
        bisect.insort(self.arr, num)       # 二分定位 O(log n) + 插入挪动 O(n)

    def findMedian(self):
        n = len(self.arr)
        if n % 2 == 1:
            return float(self.arr[n // 2])  # 奇数取正中
        return (self.arr[n // 2 - 1] + self.arr[n // 2]) / 2.0  # 偶数取平均

