        self.large = []   # 较大一半的最小堆

    def addNum(self, num):
        heapq.heappush(self.small, -num)             # 先进较小一半
        heapq.heappush(self.large, -heapq.heappop(self.small))  # 最大值挪给 large
        if len(self.large) > len(self.small):        # 平衡：small 最多多 1
            heapq.heappush(self.small, -heapq.heappop(self.large))

    def findMedian(self):
        if len(self.small) > len(self.large):
            return float(-self.small[0])             # 奇数：small 堆顶
        return (-self.small[0] + self.large[0]) / 2.0  # 偶数：两堆顶平均

