// 最小堆的两个辅助操作（最大堆通过存负数模拟）
function heapPush(heap, x) {
  heap.push(x);                  // 新元素先放到堆底
  let i = heap.length - 1;
  while (i > 0) {                // 上浮：比父节点小就交换
    const p = (i - 1) >> 1;
    if (heap[i] >= heap[p]) break;
    [heap[i], heap[p]] = [heap[p], heap[i]];
    i = p;
  }
}

function heapPop(heap) {
  const top = heap[0];           // 弹出堆顶
  const last = heap.pop();
  if (heap.length) {
    heap[0] = last;              // 末尾元素补到堆顶
    let i = 0;
    for (;;) {                   // 下沉：与较小的孩子交换
      const l = 2 * i + 1, r = 2 * i + 2;
      let m = i;
      if (l < heap.length && heap[l] < heap[m]) m = l;
      if (r < heap.length && heap[r] < heap[m]) m = r;
      if (m === i) break;
      [heap[i], heap[m]] = [heap[m], heap[i]];
      i = m;
    }
  }
  return top;
}

/**
 * 数据流中位数：对顶堆，small 存较小一半（负数模拟大根堆），large 存较大一半
 */
var MedianFinder = function () {
  this.small = [];  // 最大堆（存负数）：堆顶是较小一半的最大值
  this.large = [];  // 最小堆：堆顶是较大一半的最小值
};

/**
 * @param {number} num
 * @return {void}
 */
MedianFinder.prototype.addNum = function (num) {
  heapPush(this.small, -num);                 // 先放进较小的一半（存负数模拟最大堆）
  heapPush(this.large, -heapPop(this.small)); // small 的最大值挪给 large，保证跨堆有序
  if (this.large.length > this.small.length)  // 平衡：约定 small 最多多 1
    heapPush(this.small, -heapPop(this.large)); // large 多了一个，最小值挪回 small
};

/**
 * @return {number}
 */
MedianFinder.prototype.findMedian = function () {
  if (this.small.length > this.large.length)
    return -this.small[0];                    // 总数为奇数：较小一半的最大值（负号还原）
  return (-this.small[0] + this.large[0]) / 2;  // 总数为偶数：中间两个数取平均
};

