type MedianFinder struct {
	small []int // 存负数：较小一半的最大堆（最小堆存负数模拟）
	large []int // 较大一半的最小堆
}

// heapPush 向最小堆压入元素（上浮）
func heapPush(h *[]int, x int) {
	*h = append(*h, x) // 新元素先放到堆底
	i := len(*h) - 1
	for i > 0 { // 上浮：比父节点小就交换
		p := (i - 1) / 2
		if (*h)[i] >= (*h)[p] {
			break
		}
		(*h)[i], (*h)[p] = (*h)[p], (*h)[i]
		i = p
	}
}

// heapPop 弹出最小堆堆顶（下沉）
func heapPop(h *[]int) int {
	hp := *h
	top := hp[0] // 弹出堆顶
	*h = hp[:len(hp)-1]
	if len(*h) > 0 {
		(*h)[0] = hp[len(hp)-1] // 末尾元素补到堆顶
		i, sz := 0, len(*h)
		for { // 下沉：与较小的孩子交换
			l, r, m := 2*i+1, 2*i+2, i
			if l < sz && (*h)[l] < (*h)[m] {
				m = l
			}
			if r < sz && (*h)[r] < (*h)[m] {
				m = r
			}
			if m == i {
				break
			}
			(*h)[i], (*h)[m] = (*h)[m], (*h)[i]
			i = m
		}
	}
	return top
}

func MedianFinderConstructor() MedianFinder {
	return MedianFinder{}
}

func (mf *MedianFinder) AddNum(num int) {
	heapPush(&mf.small, -num)                // 先放进较小的一半（存负数模拟最大堆）
	heapPush(&mf.large, -heapPop(&mf.small)) // small 的最大值挪给 large，保证跨堆有序
	if len(mf.large) > len(mf.small) {       // 平衡：约定 small 最多多 1
		heapPush(&mf.small, -heapPop(&mf.large)) // large 多了一个，最小值挪回 small
	}
}

func (mf *MedianFinder) FindMedian() float64 {
	if len(mf.small) > len(mf.large) {
		return float64(-mf.small[0]) // 总数为奇数：较小一半的最大值
	}
	// 总数为偶数：中间两个数取平均
	return float64(-mf.small[0]+mf.large[0]) / 2.0
}

