class Solution {
public:
    int findMaximizedCapital(int k, int w, vector<int>& profits, vector<int>& capital) {
        int n = (int)profits.size();
        vector<pair<int, int>> projects(n);   // (启动资本, 利润)
        for (int i = 0; i < n; ++i)
            projects[i] = {capital[i], profits[i]};
        // 按『启动所需资本』升序排序，便于用指针增量解锁可做的项目
        sort(projects.begin(), projects.end());
        priority_queue<int> heap;   // 大根堆：装当前资本 w 能启动的所有项目（存利润）
        int j = 0;                  // 指向第一个还没入堆的项目；w 只增不减，指针不会回头
        for (int round = 0; round < k; ++round) {   // 最多做 k 个项目
            while (j < n && projects[j].first <= w) {
                heap.push(projects[j].second);   // 资本够了，项目解锁，利润压入堆
                ++j;
            }
            if (heap.empty()) break;   // 没有任何可做的项目，提前结束
            w += heap.top();           // 贪心：做当前可做项目中利润最大的
            heap.pop();
        }
        return w;
    }
};

