var findMaximizedCapital = function (k, w, profits, capital) {
  // 按『启动所需资本』升序排序，便于用指针增量解锁可做的项目
  const projects = capital
    .map((c, i) => [c, profits[i]])
    .sort((a, b) => a[0] - b[0]);

  // 大根堆：存负利润的最小堆，堆顶即当前可做项目中利润最大的
  const heap = [];
  const push = (x) => {
    heap.push(x);              // 新元素先放到堆底
    let i = heap.length - 1;
    while (i > 0) {            // 上浮：比父节点小就交换
      const p = (i - 1) >> 1;
      if (heap[i] >= heap[p]) break;
      [heap[i], heap[p]] = [heap[p], heap[i]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0];       // 弹出堆顶（当前最大利润）
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;          // 末尾元素补到堆顶
      let i = 0;
      for (;;) {               // 下沉：与较小的孩子交换
        const l = 2 * i + 1, r = 2 * i + 2;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]];
        i = m;
      }
    }
    return top;
  };

  let j = 0;   // 指向第一个还没入堆的项目；w 只增不减，指针不会回头
  for (let round = 0; round < k; round++) {   // 最多做 k 个项目
    while (j < projects.length && projects[j][0] <= w) {
      push(-projects[j][1]);   // 资本够了，项目解锁，负利润入堆
      j++;
    }
    if (!heap.length) break;   // 没有任何可做的项目，提前结束
    w += -pop();               // 贪心：做当前可做项目中利润最大的
  }
  return w;
};

