func findMaximizedCapital(k int, w int, profits []int, capital []int) int {
	n := len(profits)
	type project struct {
		cap int // 启动资本
		pro int // 利润
	}
	projects := make([]project, n)
	for i := 0; i < n; i++ {
		projects[i] = project{capital[i], profits[i]}
	}
	// 按『启动所需资本』升序排序，便于用指针增量解锁可做的项目
	sort.Slice(projects, func(i, j int) bool { return projects[i].cap < projects[j].cap })

	// 大根堆：存负利润的最小堆，堆顶即当前可做项目中利润最大的
	heap := []int{}
	push := func(x int) {
		heap = append(heap, x) // 新元素先放到堆底
		i := len(heap) - 1
		for i > 0 { // 上浮：比父节点小就交换
			p := (i - 1) / 2
			if heap[i] >= heap[p] {
				break
			}
			heap[i], heap[p] = heap[p], heap[i]
			i = p
		}
	}
	pop := func() int {
		top := heap[0] // 弹出堆顶（当前最大利润的负值）
		heap[0] = heap[len(heap)-1]
		heap = heap[:len(heap)-1]
		i, sz := 0, len(heap)
		for { // 下沉：与较小的孩子交换
			l, r, m := 2*i+1, 2*i+2, i
			if l < sz && heap[l] < heap[m] {
				m = l
			}
			if r < sz && heap[r] < heap[m] {
				m = r
			}
			if m == i {
				break
			}
			heap[i], heap[m] = heap[m], heap[i]
			i = m
		}
		return top
	}

	j := 0 // 指向第一个还没入堆的项目；w 只增不减，指针不会回头
	for round := 0; round < k; round++ { // 最多做 k 个项目
		for j < n && projects[j].cap <= w {
			push(-projects[j].pro) // 资本够了，项目解锁，负利润入堆
			j++
		}
		if len(heap) == 0 { // 没有任何可做的项目，提前结束
			break
		}
		w += -pop() // 贪心：做当前可做项目中利润最大的
	}
